using System.Security.Cryptography;
using UnityFontReplacer.Swizzle;

internal static class Ps5SwizzleChecks
{
    public static void Run()
    {
        // SHA-256 results generated by Python UFR ps5_swizzle_bytes with
        // exactly the same data, including 31 unused trailing bytes.
        foreach (var (w, h, bpe, expected) in new[]
        {
            (32, 16, 1, "f4cfa9fe1bc39438f59ef6f384e5c257ce96504f60c493960380ebad11f73731"),
            (512, 256, 1, "56fa155492a9c0f7ac53c40af61a2aa83240246355dea5d996452e13558b38f0"),
            (128, 32, 2, "e8e0136f6eb2bb69a202ac491639fe483c7e6266cc9f6a8b4d4017e23cda6a68"),
            (64, 128, 3, "ec9ce990615c3bcc1d2570c1a3778263b7318ec5bacb35fce1fd8cb8f00cc297"),
            (128, 32, 4, "02e0c6fcd90880d22c4bb30ea6386f7785d7ee0f0e3da7abd96aeb4e8617ca0a"),
            (64, 24, 4, "fccfff805ae3027ac3a5631358976ef0be165221dfcbc2ce4077d28e22c73246"),
        })
        {
            byte[] raw = Sample(w * h * bpe + 31);
            byte[] encoded = Ps5Swizzle.SwizzleUncompressed(raw, w, h, bpe);
            CheckHash(encoded, expected);
            if (!Ps5Swizzle.UnswizzleUncompressed(encoded, w, h, bpe)
                    .AsSpan().SequenceEqual(raw.AsSpan(0, w * h * bpe)))
                throw new InvalidDataException($"PS5 base-level round trip failed for {w}x{h}/{bpe}.");
        }

        // Python applies clockwise rotation before tiling Alpha8. Atlas metadata
        // stays 256x128 even though the payload is tiled as 128x256.
        byte[] alpha = Sample(256 * 128);
        byte[] stored = Ps5Swizzle.EncodeAlpha8Atlas(alpha, 256, 128);
        CheckHash(stored, "1a45dc63879335ed14dc66bbde02ca7ba410eeed56e32a01dcdca91ee4f5d5f5");
        if (!Ps5Swizzle.DecodeAlpha8Atlas(stored, 256, 128).AsSpan().SequenceEqual(alpha))
            throw new InvalidDataException("PS5 Alpha8 atlas round trip failed.");
    }

    private static byte[] Sample(int size)
    {
        var bytes = new byte[size];
        for (int i = 0; i < size; i++)
            bytes[i] = (byte)((i * 1299721) ^ (i >> 2) ^ (i >> 8));
        return bytes;
    }

    private static void CheckHash(byte[] bytes, string expected)
    {
        if (!Convert.ToHexString(SHA256.HashData(bytes)).Equals(expected, StringComparison.OrdinalIgnoreCase))
            throw new InvalidDataException("PS5 bytes did not match Python UFR's golden transform.");
    }
}
